# 견본4 Claude 담당 9·11·13·15번 (9번 4.4점, 11번 4.5점, 13·15번 4.7점)
ITEMS = {
  9: dict(body=r"""세 상수 \(a\), \(b\), \(c\)에 대하여 시각 \(t=0\)일 때 출발하여 수직선 위를 움직이는 점 \(\mathrm{P}\)의 시각 \(t\) \((t\ge0)\)에서의 위치 \(x\)가
\[x=t^4+at^3+bt^2+ct\]
이다. 점 \(\mathrm{P}\)의 시각 \(t\)에서의 속도 \(v(t)\)가 \(v(1)=v(4)=0\), \(v(2)&gt;0\)이고, 점 \(\mathrm{P}\)는 출발한 후 운동 방향을 한 번만 바꾼다. 점 \(\mathrm{P}\)가 운동 방향을 바꾸는 시각에서의 점 \(\mathrm{P}\)의 위치는?""",
          choices=['-12', '-17', '-22', '-27', '-32'],
          ans=4,
          key='M52', src='2025학년도 수능 11번',
          var=r"[함수 교체] 삼차 위치 \(t^3-\frac32t^2-6t\) → 계수를 모르는 사차 위치 \(t^4+at^3+bt^2+ct\) (속도가 삼차식) · [역문제화] 속도가 \(0\)인 두 시각 \(t=1\), \(t=4\)와 '운동 방향을 한 번만 바꾼다'로 속도의 꼴 \(4(t-1)^2(t-4)\) 또는 \(4(t-1)(t-4)^2\)를 정함 · [함정 추가] 속도가 \(0\)이어도 부호가 바뀌지 않으면 방향 전환이 아님, 두 후보 중 \(t=2\)의 속도 부호로 택일 · [구하는 대상 변경] 방향 전환 시각의 가속도 → 위치",
          level='중',
          sol=r"\(v=v(t)=\dfrac{dx}{dt}=4t^3+3at^2+2bt+c\)이고 \(v(1)=v(4)=0\)이므로 실수 \(r\)에 대하여 \(v=4(t-1)(t-4)(t-r)\)로 놓을 수 있다. 점 \(\mathrm{P}\)는 \(v\)의 부호가 바뀌는 시각에 운동 방향을 바꾼다. \(r\ne1\)이고 \(r\ne4\)이면 \(t=1\)과 \(t=4\)의 좌우에서 모두 \(v\)의 부호가 바뀌므로 운동 방향을 두 번 이상 바꾸어 조건을 만족시키지 않는다. 따라서 \(r=1\) 또는 \(r=4\)이다. (i) \(r=1\)이면 \(v=4(t-1)^2(t-4)\)이고 \(t=2\)에서 \(v=-8&lt;0\)이므로 조건을 만족시키지 않는다. (ii) \(r=4\)이면 \(v=4(t-1)(t-4)^2\)이고 \(t=2\)에서 \(v=16&gt;0\)이다. 이때 \(v\)의 부호는 \(t=1\)에서만 바뀌므로 점 \(\mathrm{P}\)는 \(t=1\)에서만 운동 방향을 바꾼다. \(v=4t^3-36t^2+96t-64\)이므로 \(a=-12\), \(b=48\), \(c=-64\)이고 \(x=t^4-12t^3+48t^2-64t=t(t-4)^3\)이다. 따라서 구하는 위치는 \(t=1\)일 때 \(1\times(-3)^3=-27\)이다.",
          fast=r"속도가 \(0\)인 시각이 \(1\), \(4\)인데 방향 전환은 한 번이므로 둘 중 하나는 속도의 부호가 바뀌지 않는 시각이다. \(v=4(t-1)^2(t-4)\)이면 \(v(2)&lt;0\)이므로 \(v=4(t-1)(t-4)^2\), 방향 전환은 \(t=1\). \(x=t(t-4)^3\)이면 \(x'=(t-4)^2(4t-4)\)이 \(v\)와 같으므로 \(x(1)=-27\).",
          note=r"원본은 속도 \(3(t-2)(t+1)\)의 양의 근 \(t=2\)에서 가속도를 바로 구했지만, 여기서는 위치가 사차식이라 속도가 \(0\)인 두 시각 중 하나가 부호가 바뀌지 않는 시각이어야 하므로 두 경우를 세우고 \(t=2\)의 속도 부호로 하나를 고른 뒤 위치를 구한다.",
          wrong=r"\(t=2\)의 속도 조건을 보지 않고 \(v=4(t-1)^2(t-4)\)를 택하면 방향 전환 시각 \(t=4\)에서 \(x=t^4-8t^3+18t^2-16t\)의 값 \(-32\)(⑤)",
          author='claude'),

  11: dict(body=r"""최고차항의 계수가 \(1\)이고 \(f(0)=0\)인 이차함수 \(f(x)\)에 대하여 함수 \(g(x)=(x^2-4x)f(x)\)가 다음 조건을 만족시킬 때, \(g(1)\)의 값은?""",
           cond=[('가', r"집합 \(\{x\,|\,g(x)=0\}\)의 원소의 개수는 \(2\)이다."),
                 ('나', r"함수 \(g(x)\)는 극댓값을 갖는다.")],
           choices=['-3', '0', '3', '6', '9'],
           ans=5,
           key='D46', src='2025년 수능특강 [25009-0101]',
           var=r"[숫자 변경] \(g(x)=(x^2-2x)f(x)\) → \((x^2-4x)f(x)\) · [조건 변경] (나) '극댓값을 갖지 않는다' → '극댓값을 갖는다': 원본에서 버리던 \(f(x)=x(x-4)\) 쪽, 즉 \(g(x)=x^2(x-4)^2\)를 택함 · [구하는 대상 변경] 극솟값 → \(g(1)\)",
           level='중',
           sol=r"\(f(0)=0\)이므로 \(f(x)=x(x+p)\) (\(p\)는 상수)로 놓으면 \(g(x)=x^2(x-4)(x+p)\)이다. \(g(x)=0\)의 해는 \(0\), \(4\), \(-p\)이므로 (가)에서 \(-p=0\) 또는 \(-p=4\)이다. (i) \(p=0\)이면 \(g(x)=x^3(x-4)\), \(g'(x)=x^2(4x-12)\)이고 \(g'(x)\)의 부호는 \(x=3\)에서만 음에서 양으로 바뀌므로 \(g(x)\)는 극댓값을 갖지 않는다. (ii) \(p=-4\)이면 \(g(x)=x^2(x-4)^2\), \(g'(x)=4x(x-2)(x-4)\)이고 \(x=2\)에서 극댓값 \(16\)을 가지므로 (나)를 만족시킨다. 따라서 \(g(x)=x^2(x-4)^2\)이고 \(g(1)=1\times9=9\)이다.",
           fast=r"(가)에서 \(g=x^3(x-4)\) 또는 \(x^2(x-4)^2\). 앞의 것은 \(x=0\)이 삼중근이라 극값이 아니고 극소만 하나 있으므로 (나)에서 \(g=x^2(x-4)^2\) → \(g(1)=9\).",
           note=r"원본은 (나) '극댓값을 갖지 않는다'로 \(x^3(x-2)\)를 골랐지만, 여기서는 (나)를 뒤집어 사중근이 아닌 두 이중근 꼴 \(x^2(x-4)^2\)를 고르고, 극값 대신 함숫값을 묻는다.",
           wrong=r"원본처럼 (나)를 '극댓값을 갖지 않는다'로 보고 \(g(x)=x^3(x-4)\)를 택하면 \(g(1)=-3\)(①), \(g(x)=x^2(x-4)^2\)의 극솟값 \(0\)과 혼동하면 \(0\)(②)",
           author='claude'),

  13: dict(body=r"""수직선 위를 움직이는 두 점 \(\mathrm{P}\), \(\mathrm{Q}\)의 시각 \(t\) \((t\ge0)\)에서의 위치를 각각 \(x_1\), \(x_2\)라 하면
\[x_1=t^3-3t,\quad x_2=9t\]
이다. 두 점 \(\mathrm{P}\), \(\mathrm{Q}\) 사이의 거리가 처음으로 \(16\)이 되는 순간 두 점 \(\mathrm{P}\), \(\mathrm{Q}\)의 속도를 각각 \(p\), \(q\)라 할 때, \(p+q\)의 값은?""",
           choices=['18', '27', '36', '45', '54'],
           ans=1,
           key='M38', src='2025년 수능특강 [25009-0128]',
           var=r"[조건 변경] '두 점 사이의 거리가 \(12\)가 되는 순간' → '거리가 처음으로 \(16\)이 되는 순간' · [함수 교체] \(x_1=t^3+2t^2-3t\), \(x_2=t^2+5t\) → \(x_1=t^3-3t\), \(x_2=9t\) (\(x_1-x_2=t^3-12t\)의 극솟값이 정확히 \(-16\)) · [함정 추가] 원본은 \(x_1-x_2=-12\)인 순간이 없어 \(x_1-x_2=12\)만 풀었지만, 여기서는 \(x_1-x_2=-16\)인 \(t=2\)가 \(x_1-x_2=16\)인 \(t=4\)보다 먼저 옴",
           level='중',
           sol=r"\(d(t)=x_1-x_2=t^3-12t\)라 하면 두 점 사이의 거리는 \(|d(t)|\)이다. \(d'(t)=3t^2-12=3(t+2)(t-2)\)이므로 \(0\le t\le2\)에서 \(d(t)\)는 감소하고 \(t\ge2\)에서 증가하며, \(d(0)=0\), \(d(2)=-16\)이다. 따라서 \(0\le t&lt;2\)에서 \(-16&lt;d(t)\le0\)이므로 \(|d(t)|&lt;16\)이고, \(t=2\)에서 처음으로 \(|d(t)|=16\)이 된다. (\(d(t)=16\)은 \((t-4)(t+2)^2=0\)에서 \(t=4\)이므로 더 나중이다.) 두 점의 속도는 \(v_1=3t^2-3\), \(v_2=9\)이므로 \(p=12-3=9\), \(q=9\)이고 \(p+q=18\)이다.",
           fast=r"\(d=t^3-12t\)는 \(t=2\)에서 극솟값 \(-16\)을 가지므로 거리가 처음 \(16\)이 되는 순간은 \(t=2\)이고, 이때 \(d'(2)=0\)이라 \(p=q=9\) → \(p+q=18\).",
           note=r"원본은 \(t\ge0\)에서 \(x_1-x_2\)의 최솟값이 \(-12\)보다 커서 \(x_1-x_2=12\)만 풀면 되었지만, 여기서는 \(x_1-x_2\)의 극솟값이 정확히 \(-16\)이라 거리 \(16\)이 처음 되는 순간이 \(x_1-x_2=-16\) 쪽에서 오고 그 순간 두 점의 속도가 같다.",
           wrong=r"원본처럼 \(x_1-x_2=16\)만 풀어 \(t=4\)를 쓰면 \(p=45\), \(q=9\)에서 \(54\)(⑤), 그때 점 \(\mathrm{P}\)의 속도만 쓰면 \(45\)(④), \(p-q=d'(4)\)를 구하면 \(36\)(③)",
           author='claude'),

  15: dict(body=r"""\(15\) 이하의 자연수 \(k\)와 함수 \(f(x)=x^3-6x^2+kx\)에 대하여 함수
\[g(x)=\int_1^x\{f(x)-f(t)\}\times\{f(t)\}^2\,dt\]
가 오직 하나의 극값을 갖도록 하는 \(k\)의 개수는?""",
           choices=['3', '4', '5', '6', '7'],
           ans=3,
           key='I63', src='2022학년도 수능 6월 모의평가 20번',
           var=r"[조건 변경] 아래끝 \(a\)를 움직이던 것 → 아래끝을 \(1\)로 고정하고 \(f\)의 일차항 계수 \(k\)를 움직임, '모든 \(a\)의 값의 합' → '\(15\) 이하의 자연수 \(k\)의 개수' (단답형 → 5지선다) · [함수 교체] 고정된 삼차함수 \(x^3-12x^2+45x+3\) → \(k\)를 포함한 \(x^3-6x^2+kx\), 지수 \(4\) → \(2\) · [함정 추가] \(f'\)의 판별식 등호 \(k=12\) (\(f'=3(x-2)^2\))와 \(f'\)의 근이 아래끝 \(1\)과 겹치는 \(k=9\): 분석집 방향 '도함수의 부호가 바뀌지 않으면 아래끝을 겹치지 않아도 극값이 하나'를 겹치는 경우와 함께 세게 함",
           level='중상',
           sol=r"\(\displaystyle g(x)=f(x)\int_1^x\{f(t)\}^2dt-\int_1^x\{f(t)\}^3dt\)이므로 \(\displaystyle g'(x)=f'(x)\int_1^x\{f(t)\}^2dt+\{f(x)\}^3-\{f(x)\}^3=f'(x)H(x)\)이다. 여기서 \(\displaystyle H(x)=\int_1^x\{f(t)\}^2dt\)이고, \(\{f(t)\}^2\ge0\)이며 \(\{f(t)\}^2=0\)인 \(t\)는 유한개이므로 \(x&gt;1\)이면 \(H(x)&gt;0\), \(x&lt;1\)이면 \(H(x)&lt;0\)이다. 따라서 \(g'(x)\)의 부호는 \(f'(x)(x-1)\)의 부호와 같다. \(f'(x)=3x^2-12x+k\)이고 이차방정식 \(f'(x)=0\)의 판별식을 \(D\)라 하면 \(\dfrac D4=36-3k\)이다. (i) \(k\ge12\)이면 모든 실수 \(x\)에 대하여 \(f'(x)\ge0\)이고 \(f'(x)=0\)인 \(x\)는 많아야 하나이므로 \(g'(x)\)의 부호는 \(x=1\)에서만 바뀐다. 즉 \(g(x)\)는 오직 하나의 극값을 갖는다. (ii) \(k&lt;12\)이면 \(f'(x)=3(x-\alpha)(x-\beta)\) \((\alpha&lt;\beta)\)이다. \(1\ne\alpha\)이고 \(1\ne\beta\)이면 \(g'(x)\)의 부호가 \(x=\alpha\), \(\beta\), \(1\)에서 모두 바뀌어 극값이 \(3\)개이다. \(1\)이 \(\alpha\), \(\beta\) 중 하나이면 \(f'(1)=k-9=0\)에서 \(k=9\)이고 \(f'(x)=3(x-1)(x-3)\)이다. 이때 \(g'(x)=3(x-3)\times(x-1)H(x)\)이고 \((x-1)H(x)\ge0\)이므로 \(g'(x)\)의 부호는 \(x=3\)에서만 바뀌어 극값은 하나이다. 따라서 조건을 만족시키는 \(k\)는 \(9\), \(12\), \(13\), \(14\), \(15\)이고 그 개수는 \(5\)이다.",
           fast=r"\(g'=f'(x)\displaystyle\int_1^x f^2\)이고 적분 부분의 부호는 \(x-1\)이므로 \(g'\)의 부호는 \((3x^2-12x+k)(x-1)\). 부호가 한 번만 바뀌려면 \(f'\)의 부호가 바뀌지 않거나(\(\frac D4=36-3k\le0\), \(k=12\sim15\)) \(f'\)의 근 하나가 \(1\)이어야 한다(\(k=9\)) → \(5\)개.",
           note=r"원본은 \(f'\)의 두 근 \(3\), \(5\) 중 하나에 아래끝 \(a\)를 겹치는 경우만 셌지만, 여기서는 아래끝이 \(1\)로 고정되고 \(k\)에 따라 \(f'\)의 부호가 바뀌지 않는 경우(\(k\ge12\), 등호 포함)와 \(f'\)의 근 하나가 \(1\)과 겹치는 경우(\(k=9\))를 함께 세야 한다.",
           wrong=r"판별식 등호를 빼서 \(k=12\)를 놓치거나 \(f'\)의 근이 \(1\)과 겹치는 \(k=9\)를 놓치면 \(4\)(②), 둘 다 놓쳐 \(k=13\), \(14\), \(15\)만 세면 \(3\)(①)",
           author='claude'),
}
